@scorer(metrics=[accuracy(), stderr()])
def agentic_humaneval_scorer() -> Scorer:
    """
    Scorer for agentic solvers that includes metadata about the solving process.

    Checks for human intervention flags and includes attempt history.
    """

    async def score(state: TaskState, target: Target) -> Score:
        agentic_data = state.metadata.get('agentic_results', {})
        if agentic_data.get('flag_for_human_intervention', False):
            state.completed = True
            return Score(value=INCORRECT, answer='[flag_for_human_intervention]', explanation='The model flagged the tests for human intervention.', metadata={'human_intervention_requested': True, 'reason': 'Tests flagged as potentially flawed'})
        answer = find_code(state.output.completion if state.output else '')
        test_code = state.metadata.get('test_patch')
        code = [state.metadata.get('prompt', '') + '\n    pass\n'] + ([state.metadata.get('test', '') + '\n'] if test_code is None else []) + [answer + '\n'] + ([test_code + '\n'] if test_code is not None else []) + [f"check({state.metadata.get('entry_point', 'solution')})"]
        try:
            result = await sandbox().exec(cmd=['python', '-c', ''.join(code)], timeout=VERIFY_TIMEOUT, timeout_retry=False)
        except TimeoutError:
            result = ExecResult(False, 1, '', 'Verification timed out.')
        except Exception as e:
            result = ExecResult(False, 1, '', f'Verification failed: {str(e)}')
        score_metadata = {'verification_result': result.success, 'stdout': result.stdout, 'stderr': result.stderr}
        if agentic_data:
            attempt_history = agentic_data.get('attempt_history', [])
            score_metadata.update({'agentic_attempts': agentic_data.get('max_attempts', 1), 'total_messages': agentic_data.get('total_messages', 0), 'used_feedback': agentic_data.get('used_feedback', False), 'attempt_history': attempt_history, 'attempts_made': len(attempt_history), 'final_attempt_success': attempt_history[-1]['success'] if attempt_history else False})
        return Score(value=CORRECT if result.success else INCORRECT, answer=answer, explanation=''.join(['The following verification code was executed:\n\n', '```python\n\n', *code, '\n```\n', f'\nThe submission was incorrect\n\n{result.stderr}']) if not result.success else '', metadata=score_metadata)
    return score

def find_code(completion: str) -> str:
    """
    Extract code from completion, handling markdown code blocks.

    Args:
        completion: The model's completion text

    Returns:
        Extracted code string
    """
    pattern_1 = re.compile('```python\\n(.*?)```', re.DOTALL)
    pattern_2 = re.compile('```\\n(.*?)```', re.DOTALL)
    matches = pattern_1.findall(completion) + pattern_2.findall(completion)
    if matches:
        return matches[-1]
    else:
        return completion

